"""Rebuild 120 original Structure 1 questions. No external packages or source questions."""
from structure_common import *

b=Bank(1)

# S1.1: six different shared-course skills, four independent contexts each.
cases=[
('A sealed gas is compressed at constant temperature.','The average separation of its particles decreases.',['The particles become smaller.','The number of particles decreases.','The particles stop moving.'],'Particle size and number are unchanged; the volume available per particle decreases.'),
('A molecular liquid freezes without decomposing.','Its particles become arranged in a more ordered structure.',['Each molecule splits into atoms.','All particle motion ceases.','The particles become electrically charged.'],'Freezing changes arrangement and freedom of motion; particles still vibrate and retain chemical identity.'),
('A liquid evaporates from an open dish at a steady temperature.','Some surface particles escape into the gas phase.',['Every particle has the same kinetic energy.','Covalent bonds inside every molecule break.','The liquid must be at its boiling point.'],'Evaporation is escape from the surface and can occur below the boiling point; it does not require molecular decomposition.'),
('A gas spreads through an evacuated vessel.','Particles move randomly and occupy the available volume.',['A continuous fluid pushes every particle together.','Particles expand to fill the vessel.','Particles attract one another into a fixed lattice.'],'Random motion disperses particles through the available space; the particles themselves do not expand.')]
for v,(stem,answer,wrong,reason) in enumerate(cases,1):
    b.add('S11-particle-motion','S1.1',v,'Particle behaviour',stem+' Which statement describes the change?',options=[answer]+wrong,reason=reason)

models=[(['AA']*8,'a pure element','Every particle contains only element A.'),(['AB']*8,'a pure compound','All particles contain both elements bonded in the same ratio.'),(['AA','BB']*4,'a mixture of elements','There are two elemental substances and no particle contains both elements.'),(['AB','AA']*4,'a mixture of an element and a compound','AB is a compound and AA is an elemental substance.')]
classifications=['a pure element','a pure compound','a mixture of elements','a mixture of an element and a compound']
for v,(groups,answer,reason) in enumerate(models,1):
    b.add('S11-classification','S1.1',v,'Classifying a particle sample',f'The diagram is a particle model of sample {v}. A and B represent different elements. How should the sample be classified?',options=[answer]+[x for x in classifications if x!=answer],reason=reason,diagram=particles(groups))

separations=[('sand mixed with aqueous sodium chloride','Recover dry sand and solid sodium chloride.','Filter the mixture; the insoluble sand remains as residue.','Wash and dry the sand, then evaporate water from the filtrate or concentrate and crystallize the salt.','The components retain their identities; filtration and evaporation exploit physical properties.'),
('water containing an insoluble oil layer','Recover the oil layer and the water layer.','Allow the immiscible liquids to settle in a separating funnel.','Open the tap to drain the lower water layer and close it before the oil reaches the tap.','Immiscibility and density differences permit physical separation; no new substance is required.'),
('a mixture of ethanol and water, with boiling points 78 and 100 °C at the working pressure','Obtain a fraction enriched in ethanol.','Use fractional distillation with a fractionating column.','Ethanol is more volatile, so the vapour and early condensate are richer in ethanol; simple complete separation is not implied.','The two substances are not chemically bonded to one another and retain their identities.'),
('two soluble food dyes with different affinities for a stationary phase and a solvent','Separate small samples of both dyes for comparison.','Use chromatography with a suitable stationary phase and mobile phase.','Different distributions between the phases give different migration distances.','Chromatography separates a mixture without changing the chemical identities of its components.')]
for v,(mix,target,s1,s2,s3) in enumerate(separations,1):
    b.add('S11-separation','S1.1',v,'Choosing a separation',f'A laboratory has {mix}. {target}',parts=[P('Describe a suitable separation procedure and the property that makes it work.',A(s1),Rn(s2)),P('Explain why this sample is a mixture rather than a single compound.',Rn(s3))])

for v,(mp,t0,tf) in enumerate([(35,15,60),(48,22,72),(62,40,85),(18,4,40)],1):
    xs=[0,2,6,8];ys=[t0,mp,mp,tf]
    b.add('S11-heating-evidence','S1.1',v,'Interpreting a heating trace',f'The constructed trace shows a pure molecular solid heated at constant pressure with a constant-power heater. Heat loss is negligible and the material does not decompose. The temperature is constant at {mp} °C from 2 to 6 min.',kind='data-based',diagram=plot(xs,ys,'Time / min','Temperature / °C','Constructed heating data',labels=True),parts=[P('State the physical process occurring from 2 to 6 min.',A('Melting: solid and liquid coexist.')),P('Explain why the temperature is constant despite continued energy transfer.',Rn('The mean kinetic energy of the particles remains constant.'),Rn('The energy supplied changes particle arrangement and increases intermolecular potential energy.')),P('Describe how particle motion differs before and after the plateau.',A('Before the plateau, particles vibrate about fixed positions; after it, particles can move past one another in the liquid.'))])

for v,(tc,wrongtc) in enumerate([(27,54),(47,94),(77,154),(127,254)],1):
    tk=tc+273;double=2*tk-273
    b.add('S11-kelvin','S1.1',v,'Temperature and kinetic energy',f'For this model use 0 °C = 273 K. A gas initially at {tc} °C is heated until its mean translational kinetic energy doubles. What is its final temperature?',options=[f'{double} °C',f'{wrongtc} °C',f'{tk} °C',f'{2*tk} °C'],reason=f'Mean translational kinetic energy is proportional to absolute temperature. The initial temperature is {tk} K; the final temperature is {2*tk} K, which is {double} °C.')

changes=[('solid iodine forms purple vapour in a closed vessel',False,'Iodine molecules remain iodine molecules; only the physical state changes.'),('magnesium burns in oxygen to form magnesium oxide',True,'Atoms rearrange into magnesium oxide, a substance with a different chemical composition.'),('sugar crystals dissolve in water without reacting',False,'Sugar molecules disperse among water molecules and retain their molecular identities.'),('hydrogen and oxygen react to form water',True,'Bonds are broken and new bonds form, producing water molecules with a different chemical identity.')]
for v,(event,chemical,reason) in enumerate(changes,1):
    b.add('S11-change-model','S1.1',v,'Physical and chemical change',f'Consider the following observation: {event}.',parts=[P('Classify the change as physical or chemical and justify your answer using particles.',A('Chemical change.' if chemical else 'Physical change.'),Rn(reason)),P('State what happens to the total number of atoms of each element in a closed system during this change.',A('The number of atoms of each element is conserved; atoms are neither created nor destroyed.'))])

# S1.2: isotope arithmetic is shared; interpreting mass spectra is AHL.
for v,(el,z,a,charge) in enumerate([('Mg',12,25,2),('Cl',17,37,-1),('Al',13,27,3),('O',8,18,-2)],1):
    e=z-charge;n=a-z;ch=f'{abs(charge)}'+('+' if charge>0 else '-') if abs(charge)>1 else ('+' if charge>0 else '-')
    answer=f'{z} protons, {n} neutrons, {e} electrons'
    b.add('S12-nuclide-count','S1.2',v,'Counting subatomic particles',f'An ion of {c(el,ch)} has mass number {a} and atomic number {z}. Which inventory is correct?',options=[answer,f'{z} protons, {a} neutrons, {e} electrons',f'{z} protons, {n} neutrons, {z+charge} electrons',f'{a} protons, {z} neutrons, {e} electrons'],reason=f'Protons = {z}; neutrons = {a} − {z} = {n}; electrons = {z} − ({charge}) = {e}.')

for v,(el,z,a1,a2) in enumerate([('Ne',10,20,22),('B',5,10,11),('Si',14,28,30),('S',16,32,34)],1):
    b.add('S12-isotope-model','S1.2',v,'Comparing two isotopes',f'Two neutral atoms of {c(el)} have atomic number {z} and mass numbers {a1} and {a2}.',parts=[P('State the numbers of neutrons in the two atoms.',A(f'The isotope of mass number {a1} has {a1-z} neutrons, and the isotope of mass number {a2} has {a2-z} neutrons.')),P('Explain why their chemical properties are very similar.',Rn(f'Both neutral atoms have {z} electrons and the same electron configuration.'),Rn('Chemical behaviour depends mainly on valence electrons, rather than the number of neutrons.')),P('Explain why these atoms are isotopes of one element rather than atoms of different elements.',Rn(f'Both nuclei have {z} protons; isotopes differ in neutron number.'))])

for v,(name,m1,m2,pct) in enumerate([('X',62.0,64.0,69.0),('Y',84.0,86.0,58.0),('Q',106.0,108.0,44.0),('Z',120.0,122.0,73.0)],1):
    avg=(m1*pct+m2*(100-pct))/100
    b.add('S12-weighted-mean','S1.2',v,'Relative atomic mass',f'A constructed sample of hypothetical element {name} contains only two isotopes. Their relative isotopic masses are {m1:.1f} and {m2:.1f}, with abundances {pct:.1f}% and {100-pct:.1f}%, respectively.',parts=[P('Calculate the relative atomic mass of this sample to two decimal places.',M(f'Use the abundance-weighted mean: ({m1:.1f} × {pct:.1f} + {m2:.1f} × {100-pct:.1f}) / 100.'),A(f'The relative atomic mass is {avg:.2f}; it has no unit.')),P('Explain why the answer is closer to one isotopic mass than the other.',Rn('The mean is nearer the mass of the more abundant isotope because that isotope makes the greater contribution to the weighted mean.'))])

for v,(el,low,high,avg) in enumerate([('J',40.0,42.0,40.70),('Kx',70.0,72.0,71.20),('L',98.0,102.0,99.40),('M',130.0,134.0,132.60)],1):
    p=(high-avg)/(high-low)*100
    b.add('S12-abundance-inverse','S1.2',v,'Deducing isotope abundance',f'Constructed isotope data for hypothetical element {el} give relative isotopic masses {low:.1f} and {high:.1f}. These are the only isotopes present. The relative atomic mass of the sample is {avg:.2f}.',kind='data-based',parts=[P('Determine the percentage abundance of the lighter isotope.',M(f'Let x be its fractional abundance: {low:.1f}x + {high:.1f}(1 − x) = {avg:.2f}.'),A(f'x = {p/100:.3f}, so the lighter isotope has abundance {p:.1f}%.')),P('Predict the effect on the relative atomic mass if the lighter isotope becomes more abundant.',A('The relative atomic mass decreases towards the lighter isotopic mass.'))])

atomclaims=[('Which statement compares the nucleus with the whole atom?','The nucleus contains most of the mass but occupies a very small fraction of the volume.',['The nucleus contains most of the volume but almost no mass.','Electrons account for almost all atomic mass.','The nucleus and whole atom have similar radii.'],'Protons and neutrons account for nearly all atomic mass; the nucleus is tiny compared with the electron cloud.'),
('Which change necessarily forms an atom of a different element?','Changing the number of protons in the nucleus.',['Removing one electron.','Adding one neutron.','Changing the arrangement of electrons.'],'Atomic number, the number of protons, defines the element.'),
('A neutral atom gains one electron. What changes?','Its charge becomes −1 while its atomic number is unchanged.',['Its atomic number decreases by one.','Its mass number increases by one.','It becomes an isotope of another element.'],'Electrons determine ionic charge; the proton and nucleon counts do not change.'),
('What does the mass number of an atom count?','The total number of protons and neutrons.',['The total number of protons and electrons.','The total number of neutrons and electrons.','The relative mass including fractional isotope abundances.'],'Mass number is the integer nucleon count of one nuclide, not an abundance-weighted average.')]
for v,(stem,ans,wrong,reason) in enumerate(atomclaims,1):
    b.add('S12-nuclear-model','S1.2',v,'The nuclear model',stem,options=[ans]+wrong,reason=reason)

for v,(masses,intensities) in enumerate([([50,52,54],[20,60,20]),([64,66,68],[30,50,20]),([90,92,94],[15,35,50]),([112,114,116],[40,45,15])],1):
    total=sum(intensities);avg=sum(x*y for x,y in zip(masses,intensities))/total
    b.add('S12-mass-spectrum','S1.2',v,'Reading an isotope spectrum',f'The constructed mass spectrum is for a hypothetical monatomic element. All detected ions have charge +1, and response is proportional to isotope abundance. Use the integer peak positions as the relative isotopic masses. Dataset {v}.',level='ahl',kind='data-based',diagram=plot(masses,intensities,'m/z','Relative intensity','Constructed elemental mass spectrum',sticks=True,labels=True),parts=[P('Calculate the relative atomic mass represented by this spectrum.',M('Multiply each peak position by its intensity, sum, and divide by the total intensity.'),A(f'The relative atomic mass is ({" + ".join(str(x)+" × "+str(y) for x,y in zip(masses,intensities))}) / {total} = {avg:.2f}.')),P(f'A small number of ions of the isotope at m/z = {masses[1]} instead acquire charge +2. State their m/z value.',A(f'The doubly charged isotope would appear at m/z = {masses[1]/2:g}.')),P('State one reason isotope peak heights need not be whole-number percentages.',A('Abundances are proportions of many atoms; they are not restricted to integer percentages.'))])

# S1.3: configurations through krypton; explicit AHL spectral and ionization work.
configs=[('S',16,'',r'1s^{2}2s^{2}2p^{6}3s^{2}3p^{4}',2,'Two unpaired electrons occupy different 3p orbitals.'),('Ca',20,'2+',r'1s^{2}2s^{2}2p^{6}3s^{2}3p^{6}',0,'The ion has a filled 3p subshell.'),('Cr',24,'',r'[Ar]3d^{5}4s^{1}',6,'There are five unpaired 3d electrons and one unpaired 4s electron.'),('Cu',29,'+',r'[Ar]3d^{10}',0,'Removing the 4s electron leaves a filled 3d subshell.')]
for v,(el,z,ch,conf,unpaired,why) in enumerate(configs,1):
    b.add('S13-configurations','S1.3',v,'Ground-state electron arrangement',f'Consider the species {c(el,ch)}. The atomic number of {c(el)} is {z}.',parts=[P('Write its ground-state electron configuration. Noble-gas notation is acceptable.',A(m(conf)+'.')),P('State the number of unpaired electrons and justify it.',A(f'{unpaired} unpaired electrons.'),Rn(why))])

orbitals=[(['↑↓','↑','↑'],r'2p^{4}','It obeys both the Pauli exclusion principle and Hund’s rule.','There are four electrons in three p orbitals, with maximum unpaired electrons of parallel spin.'),(['↑↓','↑↓',''],r'2p^{4}','It obeys Pauli but is not the lowest-energy arrangement under Hund’s rule.','The doubly occupied orbitals obey Pauli, but an empty degenerate orbital remains while pairing has occurred.'),(['↑↑','↑',''],r'2p^{3}','It violates the Pauli exclusion principle.','Two electrons in the same orbital must have opposite spins.'),(['↑','↑','↑'],r'3p^{3}','It is the lowest-energy p-subshell arrangement for three electrons.','Three degenerate orbitals are singly occupied with parallel spins before pairing.')]
for v,(occ,label,ans,why) in enumerate(orbitals,1):
    wrong=['Every electron shown must occupy a different shell.','The diagram represents an s subshell.','A p subshell can contain only two electrons.'] if v in (1,4) else ['It is the unique ground-state arrangement of this subshell.','Each box can hold three electrons.','It represents three different principal energy levels.']
    b.add('S13-orbital-diagrams','S1.3',v,'Assessing an orbital diagram',f'The boxes represent the three degenerate orbitals of a {m(label)} subshell. Which statement about displayed arrangement {v} is correct?',options=[ans]+wrong,reason=why,diagram=orbital_boxes(occ,re.sub(r'\^\{(\d)\}',lambda z:z[1].translate(str.maketrans('0123456789','⁰¹²³⁴⁵⁶⁷⁸⁹')),label)))

for v,(name,observation) in enumerate([('hydrogen','separate bright visible lines'),('a low-pressure atomic vapour','discrete ultraviolet emission lines'),('a discharge tube containing one element','a reproducible set of line positions'),('an excited monatomic gas','separated lines rather than a continuous band')],1):
    b.add('S13-line-spectra-model','S1.3',v,'Evidence from atomic light',f'An emission experiment on {name} produces {observation}.',parts=[P('Explain how the lines provide evidence for quantized electronic energy levels.',Rn('Excited electrons move from higher to lower allowed energy levels.'),Rn('Each transition emits a photon whose energy equals the difference between the levels.'),Rn('Only particular energy differences are allowed, producing discrete wavelengths.')),P('Explain why the spectrum can help identify the element.',A('Different elements have different sets of allowed energy levels and therefore characteristic patterns of line wavelengths.'))])

for v,(lam,context) in enumerate([(486,'blue-green'),(434,'violet'),(656,'red'),(410,'violet-edge')],1):
    en=H*C0/(lam*1e-9);mol=en*NA/1000
    b.add('S13-photon-calculation','S1.3',v,'Energy of an emission line',f'An atomic emission line in the {context} region has wavelength {lam} nm. Use {m(r"h=6.63\times10^{-34}\ \mathrm{J\,s}")}, {m(r"c=3.00\times10^{8}\ \mathrm{m\,s^{-1}}")} and {m(r"N_{\mathrm A}=6.02\times10^{23}\ \mathrm{mol^{-1}}")}.',level='ahl',parts=[P('Calculate the energy of one photon.',M(m(r'E=hc/\lambda')+f' with wavelength {lam} × '+m(r'10^{-9}\ \mathrm{m}')+'.'),A(f'{unit(en,"J")} per photon.')),P('Calculate the energy carried by one mole of these photons, in kilojoules.',M('Multiply the photon energy by the Avogadro constant and divide by 1000.'),A(unit(mol,r'kJ\,mol^{-1}')+'.'))])

for v,lam in enumerate([91.2,110.0,126.0,145.0],1):
    freq=C0/(lam*1e-9);ion=H*freq*NA/1000
    b.add('S13-convergence','S1.3',v,'Ionization from a convergence limit',f'For a constructed atomic model, the convergence limit of a series whose lower level is the ground state is {lam:.1f} nm. Use {m(r"h=6.63\times10^{-34}\ \mathrm{J\,s}")}, {m(r"c=3.00\times10^8\ \mathrm{m\,s^{-1}}")} and {m(r"N_{\mathrm A}=6.02\times10^{23}\ \mathrm{mol^{-1}}")}.',level='ahl',parts=[P('Explain what happens to the electron at the convergence limit.',A('The electron is removed from the ground state to the ionization limit, where it is no longer bound to the atom.')),P('Calculate the corresponding molar ionization energy.',M(m(r'E=hc/\lambda')+' gives the energy per atom.'),M('Multiply by the Avogadro constant and convert joules to kilojoules.'),A(unit(ion,r'kJ\,mol^{-1}')+'.')),P('Explain why the lines of the series get closer together towards the limit.',Rn('The higher allowed energy levels become progressively closer in energy, so adjacent transition energies and line frequencies converge.'))])

for v,(label,vals,group) in enumerate([('A',[500,4560,6910,9540],1),('B',[740,1450,7730,10500],2),('C',[580,1820,2740,11600],13),('D',[790,1580,3230,4360,16000],14)],1):
    jump=max(range(len(vals)-1),key=lambda i:vals[i+1]/vals[i])+1
    b.add('S13-successive-ionization','S1.3',v,'Locating a shell boundary',f'The table gives constructed successive ionization energies for a period 3 main-group atom {label}, in '+m(r'\mathrm{kJ\,mol^{-1}}')+'.'+table(['Electron removed','Ionization energy'],list(enumerate(vals,1))),level='ahl',kind='data-based',parts=[P('Deduce the number of valence electrons and the group number.',A(f'The atom has {jump} valence electrons.'),A(f'It is in group {group}.')),P('Explain the evidence for your deduction.',Rn(f'The largest relative jump is between ionization energies {jump} and {jump+1}.'),Rn('After the valence electrons have been removed, the next electron is in an inner shell, closer to the nucleus and less shielded.'))])

# S1.4: all shared course; data always refer to the actual stated formula.
for v,(formula,mass,molar,atoms) in enumerate([('H2O',9.00,18.0,3),('CO2',6.60,44.0,3),('NH3',3.40,17.0,4),('CH4',4.80,16.0,5)],1):
    mol=mass/molar;num=mol*NA
    b.add('S14-entities','S1.4',v,'Counting molecules and atoms',f'A pure sample of {c(formula)} has mass {mass:.2f} g and molar mass {molar:.1f} '+m(r'\mathrm{g\,mol^{-1}}')+'. Use '+m(r'N_{\mathrm A}=6.02\times10^{23}\ \mathrm{mol^{-1}}')+'.',parts=[P('Calculate the amount of substance and the number of molecules.',M(m(r'n=m/M')+f' = {mass:.2f}/{molar:.1f}.'),A(f'{unit(mol,"mol")}; {unit(num,'')} molecules.')),P('Calculate the total number of atoms in the sample.',M(f'Each molecule contains {atoms} atoms.'),A(f'{unit(num*atoms,'')} atoms.'))])

for v,(formula,ar,correct,wrong) in enumerate([('Ca(NO3)2','Ca = 40.1, N = 14.0, O = 16.0',164.1,[102.1,148.1,328.2]),('Al2(SO4)3','Al = 27.0, S = 32.1, O = 16.0',342.3,[150.1,246.3,324.3]),('Mg(OH)2','Mg = 24.3, O = 16.0, H = 1.0',58.3,[41.3,82.6,56.3]),('Na2CO3','Na = 23.0, C = 12.0, O = 16.0',106.0,[83.0,74.0,212.0])],1):
    b.add('S14-formula-mass','S1.4',v,'Interpreting a chemical formula',f'Calculate the relative formula mass of {c(formula)}. Use relative atomic masses: {ar}.',options=[f'{x:.1f}' for x in [correct]+wrong],reason=f'Count every atom, applying each bracket multiplier to all atoms inside the bracket. The relative formula mass is {correct:.1f}, with no unit.')

for v,(carb,hyd,oxy,emp) in enumerate([(40.0,6.67,53.33,'CH2O'),(52.17,13.04,34.79,'C2H6O'),(54.55,9.09,36.36,'C2H4O'),(60.0,13.33,26.67,'C3H8O')],1):
    ns=[carb/12,hyd,oxy/16];base=min(ns);ratios=[x/base for x in ns]
    b.add('S14-empirical','S1.4',v,'Empirical formula from composition',f'A constructed elemental analysis gives {carb:.2f}% carbon, {hyd:.2f}% hydrogen and {oxy:.2f}% oxygen by mass. Use relative atomic masses C = 12.0, H = 1.0, O = 16.0. Allow for the rounding of the percentages.',parts=[P('Determine the empirical formula.',M('Take a 100 g sample and divide the mass of each element by its relative atomic mass.'),M('The relative amounts C:H:O are '+':'.join(f(x,4) for x in ns)+', giving approximately '+':'.join(str(round(x)) for x in ratios)+'.'),A(c(emp)+'.')),P('Explain why elemental percentages alone do not determine the molecular formula.',Rn('Different molecular formulae can be integer multiples of the same empirical formula; the molar mass is also needed.'))])

for v,(emp,em,molar,molecular) in enumerate([('CH2',14.0,84.0,'C6H12'),('CH2O',30.0,180.0,'C6H12O6'),('CH',13.0,78.0,'C6H6'),('NO2',46.0,92.0,'N2O4')],1):
    mult=round(molar/em)
    b.add('S14-molecular','S1.4',v,'Molecular and empirical formulae',f'A molecular substance has empirical formula {c(emp)}, empirical formula mass {em:.1f} and molar mass {molar:.1f} '+m(r'\mathrm{g\,mol^{-1}}')+'.',parts=[P('Determine the molecular formula.',M(f'The integer multiplier is {molar:.1f}/{em:.1f} = {mult}.'),A(c(molecular)+'.')),P('State the relationship between empirical and molecular formulae.',A('The empirical formula gives the simplest whole-number atom ratio; the molecular formula gives the actual number of each atom in one molecule.'))])

for v,(formula,molar,vol,conc) in enumerate([('NaCl',58.5,250,0.160),('KNO3',101.1,200,0.125),('Na2CO3',106.0,500,0.0800),('MgSO4',120.4,100,0.200)],1):
    mol=vol/1000*conc;mass=mol*molar
    b.add('S14-solution-preparation','S1.4',v,'Preparing a standard solution',f'A student prepares {vol:.1f} '+m(r'\mathrm{cm^3}')+f' of {conc:.3f} '+m(r'\mathrm{mol\,dm^{-3}}')+f' aqueous {c(formula)} using the pure anhydrous solid. Its molar mass is {molar:.1f} '+m(r'\mathrm{g\,mol^{-1}}')+'.',parts=[P('Calculate the mass of solid needed.',M('Convert the final solution volume to cubic decimetres and use '+m(r'n=cV')+'.'),M(m(r'm=nM')+f' = {f(mol)} × {molar:.1f}.'),A(unit(mass,'g')+'.')),P('Describe how to obtain the correct final volume after dissolving the solid.',A('Transfer the solution quantitatively to a suitable volumetric flask, rinse the original vessel into the flask, and add water to the calibration mark; mix thoroughly.'))])

for v,(start,aliquot,final) in enumerate([(0.240,20.0,100.0),(0.500,25.0,250.0),(0.150,10.0,100.0),(0.320,25.0,200.0)],1):
    ans=start*aliquot/final
    b.add('S14-dilution','S1.4',v,'Diluting a solution',f'A {aliquot:.1f} '+m(r'\mathrm{cm^3}')+f' aliquot of a {start:.3f} '+m(r'\mathrm{mol\,dm^{-3}}')+f' solution is transferred to a volumetric flask and diluted with water to a final volume of {final:.1f} '+m(r'\mathrm{cm^3}')+'. No reaction or loss of solute occurs.',parts=[P('Calculate the final concentration.',M('The amount of solute is unchanged, so '+m(r'c_1V_1=c_2V_2')+'.'),A(unit(ans,r'mol\,dm^{-3}')+'.')),P('Explain why the volume of water added is not necessarily exactly the final volume minus the aliquot volume.',Rn('Solution volumes need not be additive on mixing; the flask calibration fixes the final solution volume.'))])

# S1.5: ideal-gas predictions, inference from data and limitations.
for v,(mol,temp,pres) in enumerate([(0.250,298,101),(0.400,315,120),(0.150,285,95.0),(0.600,330,150)],1):
    vol=mol*R*temp/pres
    b.add('S15-ideal-volume','S1.5',v,'Volume predicted by the ideal-gas model',f'A sample contains {mol:.3f} mol of a gas at {temp} K and {pres:.1f} kPa. Assume ideal behaviour and use '+m(r'R=8.31\ \mathrm{kPa\,dm^3\,mol^{-1}\,K^{-1}}')+'.',parts=[P('Calculate the gas volume in cubic decimetres.',M(m(r'V=nRT/P')+'.'),A(unit(vol,'dm^3')+'.')),P('State two molecular assumptions of the ideal-gas model.',A('The volume of the particles is negligible compared with the gas volume.'),A('Intermolecular forces are negligible except during elastic collisions.'))])

for v,(p1,v1,t1,p2,t2) in enumerate([(100,2.40,300,120,330),(95.0,1.80,285,105,315),(110,3.20,320,88.0,288),(125,1.60,310,100,279)],1):
    v2=p1*v1*t2/(p2*t1)
    b.add('S15-combined-law','S1.5',v,'Changing gas conditions',f'A sealed flexible container holds a fixed amount of ideal gas. Its initial pressure, volume and temperature are {p1:.1f} kPa, {v1:.2f} '+m(r'\mathrm{dm^3}')+f' and {t1} K. Its final pressure and temperature are {p2:.1f} kPa and {t2} K.',parts=[P('Calculate the final volume.',M(m(r'P_1V_1/T_1=P_2V_2/T_2')+' for a fixed amount of ideal gas.'),A(unit(v2,'dm^3')+'.')),P('Explain, using collisions, why pressure increases when a fixed-volume gas is heated.',Rn('The average particle speed increases, so collisions with the walls occur more frequently.'),Rn('The average momentum transferred per collision also increases, giving a greater force per unit area.'))])

for v,(mass,volume,temp,pres) in enumerate([(0.660,0.375,298,101),(0.960,0.750,300,100),(1.100,0.600,295,102),(0.425,0.625,310,103)],1):
    mol=pres*volume/(R*temp);molar=mass/mol
    b.add('S15-gas-molar-mass','S1.5',v,'Molar mass from gas measurements',f'Constructed gas measurements give mass {mass:.3f} g, volume {volume:.3f} '+m(r'\mathrm{dm^3}')+f', temperature {temp} K and pressure {pres} kPa. Assume ideal behaviour. Use '+m(r'R=8.31\ \mathrm{kPa\,dm^3\,mol^{-1}\,K^{-1}}')+'.',kind='data-based',parts=[P('Determine the amount of gas and its molar mass.',M(m(r'n=PV/RT')+'.'),A(unit(mol,'mol')+'.'),M(m(r'M=m/n')+'.'),A(unit(molar,r'g\,mol^{-1}')+'.')),P('Predict the effect on the calculated molar mass if the measured mass includes a small amount of condensed liquid that does not contribute to the measured gas pressure.',Rn('The calculated molar mass is too high because the measured mass is too large for the gas amount inferred from pressure, volume and temperature.'))])

for v,(temp,k) in enumerate([(290,120),(300,180),(310,240),(320,300)],1):
    vols=[1.00,1.50,2.00,3.00];ps=[k/x for x in vols];mol=k/(R*temp)
    b.add('S15-isothermal-data','S1.5',v,'Testing the pressure-volume relation',f'The following constructed data were recorded for a fixed gas sample at {temp} K. The volumes and pressures have negligible uncertainty for this exercise. Use '+m(r'R=8.31\ \mathrm{kPa\,dm^3\,mol^{-1}\,K^{-1}}')+'.'+table(['Volume / '+m(r'\mathrm{dm^3}'),'Pressure / kPa'],[(f'{x:.2f}',f'{y:.1f}') for x,y in zip(vols,ps)]),kind='data-based',parts=[P('Show that these data are consistent with pressure being inversely proportional to volume at constant temperature.',M('Calculate pressure × volume for at least two rows.'),A(f'Every row gives PV = {k} '+m(r'\mathrm{kPa\,dm^3}')+', so pressure is inversely proportional to volume.')),P('Determine the amount of gas.',M(m(r'n=PV/RT')+'.'),A(unit(mol,'mol')+'.')),P('State why temperature must be controlled during this investigation.',Rn('Changing temperature changes PV for a fixed amount of gas, so the effect of volume alone could not be identified.'))])

deviations=[('Which conditions usually make a gas closest to ideal behaviour?','High temperature and low pressure.',['Low temperature and high pressure.','Low temperature and low volume.','High pressure close to condensation.'],'At high temperature attractions are less important relative to kinetic energy; at low pressure particle volume is a small fraction of the total.'),
('At moderate pressure and low temperature, measured gas pressure is below the ideal prediction for the same amount, volume and temperature. Which explanation is appropriate?','Attractions reduce the momentum transferred to the walls.',['Particles occupy no volume.','Every collision creates an extra particle.','Attractions increase the force on the walls.'],'Attractive interactions can reduce the wall force relative to the noninteracting model.'),
('At very high pressure, why can the finite size of gas particles cause a large deviation from the ideal model?','The volume occupied by particles is no longer negligible.',['The particles have become massless.','Temperature no longer has an absolute scale.','The number of particles is necessarily zero.'],'The free volume available for translational motion differs substantially from the total container volume.'),
('A gas is cooled towards its condensation temperature. Which ideal-gas assumption becomes especially unreliable?','Intermolecular attractions are negligible.',['Particles have mass.','Pressure is caused by collisions with a wall.','The amount of substance can be measured in moles.'],'Condensation is evidence that attractive forces can hold particles together; the noninteracting approximation fails.')]
for v,(stem,ans,wrong,reason) in enumerate(deviations,1):
    b.add('S15-deviations','S1.5',v,'Limits of the gas model',stem,options=[ans]+wrong,reason=reason)

for v,(g1,g2,m1,m2,vol,temp,pressure) in enumerate([('He','Ne',4.00,20.2,2.00,300,100),('N2','O2',28.0,32.0,1.50,298,101),('CH4','CO2',16.0,44.0,3.00,310,95.0),('Ar','Kr',39.9,83.8,2.50,320,105)],1):
    mol=pressure*vol/(R*temp)
    b.add('S15-equal-volumes','S1.5',v,'Comparing gas samples',f'Two separate containers each have volume {vol:.2f} '+m(r'\mathrm{dm^3}')+f', temperature {temp} K and pressure {pressure:.1f} kPa. One contains {c(g1)} and the other {c(g2)}. Both gases behave ideally. Their molar masses are {m1:.2f} and {m2:.2f} '+m(r'\mathrm{g\,mol^{-1}}')+', respectively. Use '+m(r'R=8.31\ \mathrm{kPa\,dm^3\,mol^{-1}\,K^{-1}}')+'.',parts=[P('Compare the numbers of gas particles in the containers and explain your answer.',A('The numbers of particles are equal.'),Rn(m(r'n=PV/RT')+' gives the same amount of substance for equal pressure, volume and temperature.')),P(f'Calculate the mass of {c(g2)} in its container.',M(f'The amount is {f(mol)} mol; multiply by its molar mass.'),A(unit(mol*m2,'g')+'.')),P('Compare the mean translational kinetic energies per particle.',A('They are equal because the gases have the same absolute temperature.'))])

