b.extend(50,P('Describe the shapes of an s orbital and a p orbital.',A('An s orbital is spherical about the nucleus.'),A('A p orbital has two lobes on opposite sides of the nucleus, commonly described as dumbbell-shaped.')))
b.extend(57,P('For hydrogen, identify the electromagnetic region of the photons emitted in the transitions n = 2 to n = 1, n = 3 to n = 2, and n = 4 to n = 3.',A('n = 2 to n = 1: ultraviolet.'),A('n = 3 to n = 2: visible.'),A('n = 4 to n = 3: infrared.')))
